INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'nl-b2g-2017', id, '2017-01-01', 1, 'https://www.logius.nl', 0, '[]', NULL FROM countries WHERE code = 'NL';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-b2g-2017', 'en', 'B2G e-invoicing mandatory for central government', 'Transposing EU Directive 2014/55/EU, the Netherlands required all central government suppliers to issue structured electronic invoices from 1 January 2017, with all public bodies obliged to be capable of receiving them. Logius operates the central infrastructure, including Digipoort and the Rijksoverheid Peppol Access Point.', '["Historical context — no action needed"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'nl-b2g-subcentral-2019', id, '2019-04-18', 0, 'https://www.logius.nl', 1, '[{"label": "Logius — e-Factureren", "url": "https://www.logius.nl/onze-dienstverlening/gegevensuitwisseling/e-factureren"}, {"label": "Netherlands Peppol Authority", "url": "https://www.logius.nl/onze-dienstverlening/domeinen/gegevensuitwisseling/peppol"}]', NULL FROM countries WHERE code = 'NL';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-b2g-subcentral-2019', 'en', 'B2G e-invoicing extended to all public sector entities (in force since April 2019)', 'From 18 April 2019 the B2G e-invoicing mandate extended beyond central government to cover all Dutch public bodies — municipalities, provinces, water boards, and other government entities. Invoices are sent via the Peppol network (BIS 3.0 / SI-UBL 2.0), the Digipoort direct gateway for high-volume suppliers, or the Government Supplier Portal for manual low-volume submission. The Netherlands Peppol Authority (formerly SimplerInvoicing) governs the national Peppol implementation under the Ministry of the Interior.', '["Confirm your Dutch public-sector invoicing runs through Peppol, Digipoort, or the Government Supplier Portal", "Verify SI-UBL 2.0 / Peppol BIS 3.0 compliance for any Dutch government contracts"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'nl-b2b-voluntary', id, '2020-01-01', 0, 'https://www.logius.nl', 1, '[{"label": "Netherlands Peppol Authority", "url": "https://www.logius.nl/onze-dienstverlening/domeinen/gegevensuitwisseling/peppol"}]', NULL FROM countries WHERE code = 'NL';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-b2b-voluntary', 'en', 'B2B e-invoicing remains voluntary, with high Peppol adoption', 'Unlike Belgium, France, Germany, Italy, and Poland, the Netherlands has taken a market-driven approach to B2B e-invoicing rather than a mandate: businesses may exchange structured e-invoices if the recipient agrees, and there is no domestic clearance or real-time reporting regime. Adoption is nonetheless high — most Dutch ERP and accounting software supports Peppol BIS 3.0 / SI-UBL 2.0 natively, and major counterparties increasingly require it as a procurement condition.', '["No domestic B2B action required, but confirm counterparties'' Peppol expectations contractually", "Consider voluntary Peppol adoption given its high market penetration among Dutch trading partners"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'nl-eyreport-2026', id, '2026-03-10', 0, 'https://www.logius.nl', 1, '[{"label": "Logius — e-Factureren", "url": "https://www.logius.nl/onze-dienstverlening/gegevensuitwisseling/e-factureren"}]', 'expected' FROM countries WHERE code = 'NL';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-eyreport-2026', 'en', 'Government signals likely domestic B2B mandate, phased 2030–2032 (advisory report, March 2026)', 'On 10 March 2026 the Dutch Secretary of Finance submitted a formal response to Parliament on implementing the EU''s VAT in the Digital Age (ViDA) e-invoicing pillar, accompanied by an external advisory report assessing two scenarios: ViDA-A (cross-border B2B only) versus ViDA-B (extending to domestic B2B). The report recommends ViDA-B on a mandatory Peppol infrastructure, phased in between 2030 and 2032, citing Italy''s VAT-gap reduction as precedent. A formal policy response is expected during summer 2026, with a public consultation on draft legislation planned for Q4 2026 — no legislation has yet been adopted.', '["Monitor the summer 2026 policy response and the planned Q4 2026 draft-legislation consultation", "If domestic B2B becomes mandatory, expect Peppol BIS 3.0 to be the likely designated channel given the B2G precedent"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'nl-vida-2030', id, '2030-07-01', 0, 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX%3A32025L0516', 1, '[{"label": "Council Directive (EU) 2025/516", "url": "https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX%3A32025L0516"}]', NULL FROM countries WHERE code = 'NL';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('nl-vida-2030', 'en', 'ViDA cross-border B2B e-invoicing and digital reporting become mandatory (confirmed EU law)', 'From 1 July 2030, under Council Directive (EU) 2025/516, structured e-invoicing and digital reporting become mandatory for all intra-Community B2B supplies — a firm EU-law floor regardless of what the Netherlands decides on domestic B2B. If the government proceeds with the ViDA-B domestic extension recommended in March 2026, virtually every VAT-registered business in the Netherlands would eventually exchange e-invoices under EN 16931, most likely via Peppol.', '["Prepare for mandatory structured e-invoicing on all intra-EU B2B trade from mid-2030, independent of the domestic B2B outcome", "Track the domestic mandate decision separately, since its scope (and 2030–2032 phasing) may exceed the EU-law minimum"]');
